'use strict';
const fs = require('node:fs'), path = require('node:path'), cp = require('node:child_process'), crypto = require('node:crypto'), assert = require('node:assert/strict');
const m = require('./manifest.json');
const sha = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
for (const item of [...m.files, ...m.unchangedInputs]) assert.equal(sha(fs.readFileSync(path.resolve(__dirname, item.path))), item.sha256, item.path + ' drift');
if (process.argv[2] === '--integrity') { console.log('CACHED_REPLAY_INTEGRITY_PASS'); process.exit(0); }
assert.equal(process.env.SOURCE_SHA, m.source, 'Only the reviewed retained source is allowed');
const dir = path.resolve(process.argv[2]);
assert(process.env.RUNNER_TEMP && dir.startsWith(path.resolve(process.env.RUNNER_TEMP) + path.sep));
assert(!fs.existsSync(dir), 'Never overwrite an earlier replay');
fs.mkdirSync(dir, { recursive: true });
const api = endpoint => JSON.parse(cp.execFileSync('gh', ['api', endpoint], { encoding: 'utf8' }));
const run = api(`repos/${m.repository}/actions/runs/${m.sourceRun}`);
const artifact = api(`repos/${m.repository}/actions/artifacts/${m.artifact.id}`);
assert.equal(run.id, m.sourceRun); assert.equal(run.head_sha, m.sourceRunner);
assert.equal(run.status, 'completed'); assert.equal(run.conclusion, 'failure');
assert.equal(artifact.id, m.artifact.id); assert.equal(artifact.name, m.artifact.name);
assert.equal(artifact.expired, false); assert.equal(artifact.size_in_bytes, m.artifact.bytes);
assert.equal(artifact.digest, 'sha256:' + m.artifact.sha256);
assert.equal(artifact.workflow_run.id, m.sourceRun); assert.equal(artifact.workflow_run.head_sha, m.sourceRunner);
const bytes = cp.execFileSync('gh', ['api', `repos/${m.repository}/actions/artifacts/${m.artifact.id}/zip`], { maxBuffer: 100 * 1024 * 1024 });
assert.equal(bytes.length, m.artifact.bytes); assert.equal(sha(bytes), m.artifact.sha256);
const archive = path.join(dir, 'source-artifact.zip'); fs.writeFileSync(archive, bytes);
const names = cp.execFileSync('unzip', ['-Z', '-1', archive], { encoding: 'utf8' }).trim().split('\n');
assert(names.length > 0 && names.every(n => !n.startsWith('/') && !n.includes('\\') && !n.split('/').includes('..') && !/^[a-z]:/i.test(n)), 'Unsafe archive path');
const inherited = path.join(dir, 'inherited'); fs.mkdirSync(inherited);
cp.execFileSync('unzip', ['-q', archive, '-d', inherited]);
assert.equal(fs.readFileSync(path.join(inherited, 'source-commit.txt'), 'utf8').trim(), m.source);
assert.equal(fs.readFileSync(path.join(inherited, 'proof-assets-commit.txt'), 'utf8').trim(), m.sourceRunner);
const app = JSON.parse(fs.readFileSync(path.join(inherited, 'simulator-app.json'), 'utf8'));
for (const key of ['bundleId', 'version', 'build', 'source', 'executableSha256', 'jsBundleSha256', 'backend']) assert.equal(app[key], m.app[key], key);
assert.deepEqual(app.platforms, ['iPhoneSimulator']); assert.equal(app.localBackend, true); assert.equal(app.distributionArtifact, false);
assert.equal(sha(fs.readFileSync(path.join(inherited, 'simulator-app.zip'))), m.app.archiveSha256);
fs.writeFileSync(path.join(dir, 'retrieval-receipt.json'), JSON.stringify({ at: new Date().toISOString(), currentRun: process.env.GITHUB_RUN_ID, replayRunner: process.env.GITHUB_SHA, sourceRun: run.id, sourceRunner: run.head_sha, source: m.source, artifactId: artifact.id, archiveSha256: sha(bytes), appArchiveSha256: m.app.archiveSha256, distributionArtifact: false, nativeBuilds: 0 }, null, 2) + '\n');
console.log('CACHED_REPLAY_RETRIEVAL_PASS');
